// ---------- 列表展示 ----------
// 酷我封面路径里的 240 是缩略档，CDN 支持 100 / 240 / 300 / 500 / 700 / 1000，统一取 500（正方形）
fn syOpus(u) {
  let s = trim(str(u ?? ''))
  if (s == '' || s == 'null') {
    return ''
  }
  let fixed = match(s, '.*(https?://[^/]+/.*)$', 1)
  if (fixed != '') {
    s = fixed
  }
  if (startsWith(s, '//')) {
    s = 'https:' + s
  }
  if (startsWith(s, 'http://')) {
    s = 'https://' + substring(s, 7)
  }
  return replace(s, '/star/albumcover/240/', '/star/albumcover/500/')
}

// infopfen / infopfennum 是采集模板值（全站只有 30603/8128、168/37 两组），不能用；按真实收听量估算
fn syTier(v) {
  if (v >= 8000) {
    return 2.2
  }
  if (v >= 3000) {
    return 2.0
  }
  if (v >= 1500) {
    return 1.7
  }
  if (v >= 700) {
    return 1.4
  }
  if (v >= 300) {
    return 1.0
  }
  if (v >= 100) {
    return 0.6
  }
  return 0.2
}

fn syRate(b) {
  if (!b) {
    return ''
  }
  let v = num(b.onclick ?? 0)
  if (v <= 0) {
    return ''
  }
  let ft = str(b.filetype ?? '')
  let bonus = ft == '完结' ? 0.7 : (contains(ft, '连载') ? 0.3 : 0)
  let s = str(round(6.3 + syTier(v) + bonus, 1))
  return contains(s, '.') ? s + '分' : s + '.0分'
}

fn syKind(b) {
  if (!b) {
    return ''
  }
  return join(compact([str(b.filetype ?? ''), syRate(b)]), ' · ')
}

// 演播：听书源要的是「谁讲的」，取 player（播音/演播名单）；playadmin 是小说原著作者，不是本字段要的内容
// 名单超过 2 人时只显示前两位 + 「等 N 人」——手机列表一行都在 15~20 字内，整串必被截断且看不出人数
// player 为空或字面量「未知」时留空；2026-10-31 核对站点网页版：详情页标题与正文展示的正是 player 名单
fn syAuthor(b) {
  if (!b) {
    return ''
  }
  let pl = trim(str(b.player ?? ''))
  if (pl == '' || pl == '未知') {
    return ''
  }
  let arr = split(pl, ',')
  let names = []
  let i = 0
  while (i < len(arr)) {
    let v = trim(str(arr[i]))
    if (v != '') {
      push(names, v)
    }
    i = i + 1
  }
  if (len(names) == 0) {
    return ''
  }
  if (len(names) <= 2) {
    return join(names, ', ')
  }
  return str(names[0]) + ', ' + str(names[1]) + ' 等 ' + str(len(names)) + ' 人'
}

