/* ---------- 诊断与镜像自愈（2026-11-14 加）----------
 * 数据链路仍是声明式、零脚本；这里只服务 actions。
 * 硬规矩：探测/写状态只能在脚本里（表达式里不行，见 源体检 第 13 项）。
 */
var SY_HOSTS = ['https://m.mekui.com', 'https://m.shuyinfm.com'];
var SY_SEARCH_HOSTS = ['https://www.shuyinfm.com', 'https://m.shuyinfm.com', 'https://m.mekui.com'];
var SY_UA = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1';

function syProbe(base) {
  var t0 = Date.now();
  try {
    var u = base + '/ecmsapi/index.php?mod=movie&act=search&keyword=' + encodeURIComponent('鬼吹灯') + '&page=1&pagesize=1';
    var r = http.get(u, { headers: { 'User-Agent': SY_UA, 'Referer': base, 'Accept': 'application/json, text/plain, */*' }, timeout: 6000 });
    var body = String((r && r.body) || '');
    var ok = !!(r && r.ok && r.status === 200 && body.indexOf('"data"') >= 0);
    return { ok: ok, st: (r && r.status) || 0, ms: Date.now() - t0 };
  } catch (e) { return { ok: false, st: 0, ms: Date.now() - t0 }; }
}
function syDiag() {
  var out = ['接口主机：'], i, r;
  for (i = 0; i < SY_HOSTS.length; i++) { r = syProbe(SY_HOSTS[i]); out.push((r.ok ? '✅ ' : '❌ ') + SY_HOSTS[i] + '  ' + r.ms + 'ms'); }
  out.push('', '搜索主机：');
  for (i = 0; i < SY_SEARCH_HOSTS.length; i++) { r = syProbe(SY_SEARCH_HOSTS[i]); out.push((r.ok ? '✅ ' : '❌ ') + SY_SEARCH_HOSTS[i] + '  ' + r.ms + 'ms'); }
  return out;
}
function syAutoHost() {
  var out = syDiag(), i, best = null, bestS = null, r;
  for (i = 0; i < SY_HOSTS.length; i++) { r = syProbe(SY_HOSTS[i]); if (r.ok && (!best || r.ms < best.ms)) { best = { u: SY_HOSTS[i], ms: r.ms }; } }
  for (i = 0; i < SY_SEARCH_HOSTS.length; i++) { r = syProbe(SY_SEARCH_HOSTS[i]); if (r.ok && (!bestS || r.ms < bestS.ms)) { bestS = { u: SY_SEARCH_HOSTS[i], ms: r.ms }; } }
  if (best) { try { vars.set('host', best.u); } catch (e) {} out.push('', '已把「接口主机」设为：' + best.u); }
  else { out.push('', '⚠️ 接口主机都不可用，未改设置'); }
  if (bestS) { try { vars.set('searchHost', bestS.u); } catch (e) {} out.push('已把「搜索主机」设为：' + bestS.u); }
  else { out.push('⚠️ 搜索主机都不可用，未改设置'); }
  return out;
}
function syResetHost() {
  try { vars.set('host', 'https://m.mekui.com'); } catch (e) {}
  try { vars.set('searchHost', 'https://www.shuyinfm.com'); } catch (e) {}
  return ['已恢复默认镜像：接口主机 m.mekui.com、搜索主机 www.shuyinfm.com'];
}
